    'rows' => '',

    /* (new_lines) Decides how to render new lines. Detauls to 'wpautop'.
    Choices of 'wpautop' (Automatically add paragraphs), 'br' (Automatically add <br>) or '' (No Formatting) */
    'new_lines' => '',

    /* (bool) Makes the input readonly. Defaults to 0 */
    'readonly' => 0,

